<template>
  <section class="ledger-page">
    <div class="page-heading ledger-heading"><div><div class="label">PERSONAL FINANCE / LEDGER</div><h1>账本 <span class="heading-slash">// OVERVIEW</span></h1><p class="muted">记录每一笔流动，月底自动对账。</p></div><div class="ledger-actions"><Button size="sm" variant="ghost" @click="aiOpen=true">自然语言记账</Button><Button size="sm" variant="ghost" @click="exportCsv">导出 CSV</Button><label class="ui-button variant-ghost size-sm import-label">导入 CSV / Excel<input type="file" accept=".csv,.xlsx,.xls,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" hidden @change="importFile" /></label><Button @click="openCreate">记一笔 ＋</Button></div></div>
    <div class="ledger-status" :class="{offline:!online}"><span class="status-dot" :class="{online}"></span><span>{{ online ? '在线 · 自动同步' : '离线 · 已保存到本机' }}</span><span v-if="syncing">正在同步…</span><button v-if="!online" class="text-button" @click="loadData">重试</button></div>
    <div class="overview-toolbar"><div class="period-picker"><button @click="shiftMonth(-1)">‹</button><input v-model="selectedMonth" type="month" aria-label="选择账本月份"/><button @click="shiftMonth(1)">›</button></div><span>{{ monthLabel }} 首页总览</span></div>
    <div class="ledger-summary-grid"><Card><template #header><div class="summary-label">本月收入</div></template><div class="summary-value income">¥{{ money(summary.income) }}</div><div class="summary-meta">{{ summary.incomeCount }} 笔流入</div></Card><Card><template #header><div class="summary-label">本月支出</div></template><div class="summary-value expense">¥{{ money(summary.expense) }}</div><div class="summary-meta">{{ summary.expenseCount }} 笔流出</div></Card><Card><template #header><div class="summary-label">本月结余</div></template><div class="summary-value" :class="summary.net>=0?'income':'expense'">¥{{ money(summary.net) }}</div><div class="summary-meta">收入 − 支出</div></Card><Card><template #header><div class="summary-label">总资产</div></template><div class="summary-value">¥{{ money(totalBalance) }}</div><div class="summary-meta">{{ accounts.length }} 个账户</div></Card></div>
    <div class="snapshot-grid"><div v-for="item in snapshots" :key="item.label" class="snapshot-item"><div><strong>{{ item.label }}</strong><small>{{ item.range }}</small></div><div><span class="income">+¥{{ money(item.income) }}</span><span class="expense">−¥{{ money(item.expense) }}</span><b :class="item.net>=0?'income':'expense'">结余 ¥{{ money(item.net) }}</b></div></div></div>
    <div class="top-chart-grid"><Card class="chart-card"><template #header><Head kicker="DAILY SPENDING" title="本月每日支出" :right="monthLabel"/></template><div ref="dailyRef" class="chart tall"/></Card><Card class="budget-overview"><template #header><Head kicker="BUDGET" title="本月支出与预算"><button class="text-button" @click="openBudget">设置</button></Head></template><div class="donut-wrap"><div ref="budgetRef" class="donut"/><div class="donut-label"><b>¥{{ money(budgetSummary.spent) }}</b><span>已支出</span></div></div><div class="budget-total"><span>预算 ¥{{ money(budgetSummary.budget) }}</span><b :class="budgetLeft<0?'expense':'income'">{{ budgetLeft<0?'超出':'剩余' }} ¥{{ money(Math.abs(budgetLeft)) }}</b></div><p v-if="!budgets.length" class="side-empty">设置分类预算后，在这里跟踪执行情况。</p></Card></div>
    <div class="middle-chart-grid"><Card class="chart-card"><template #header><Head kicker="CATEGORY RANKING" :title="`${categoryScope==='month'?'本月':'本年'}支出分类`"><div class="seg"><button :class="{active:categoryScope==='month'}" @click="categoryScope='month'">本月</button><button :class="{active:categoryScope==='year'}" @click="categoryScope='year'">本年</button></div><div class="seg"><button :class="{active:categoryLevel==='primary'}" @click="categoryLevel='primary'">一级</button><button :class="{active:categoryLevel==='secondary'}" @click="categoryLevel='secondary'">二级</button></div></Head></template><div ref="categoryRef" class="chart medium"/></Card><Card><template #header><Head kicker="BUDGET DETAIL" title="预算执行"><button class="text-button" @click="openBudget">管理</button></Head></template><div v-if="budgets.length" class="budget-list"><div v-for="budget in budgets" :key="budget.id"><div class="budget-row"><span>{{ budget.category }}</span><span>¥{{ money(budget.spent) }} / ¥{{ money(budget.budget) }}</span></div><div class="budget-track"><i :class="{over:Number(budget.spent)>Number(budget.budget)}" :style="{width:`${Math.min(100,Number(budget.spent)/Math.max(1,Number(budget.budget))*100)}%`}"/></div></div></div><p v-else class="side-empty">还没有分类预算。</p></Card></div>
    <div class="annual-chart-grid"><Card class="chart-card"><template #header><Head kicker="YEARLY CASH FLOW" :title="`${selectedYear} 年每月收支结余`" right="柱状"/></template><div ref="barRef" class="chart medium"/></Card><Card class="chart-card"><template #header><Head kicker="YEARLY TREND" :title="`${selectedYear} 年收支走势`" right="折线"/></template><div ref="lineRef" class="chart medium"/></Card></div>
    <div class="ledger-layout"><div class="ledger-main"><Card><template #header><Head kicker="MONTHLY CALENDAR" title="月度记账日历" :right="monthLabel"/></template><div class="weekdays"><span v-for="day in weekdays" :key="day">{{day}}</span></div><div class="calendar"><div v-for="cell in calendarCells" :key="cell.key" :class="['day', {blank:!cell.day,today:cell.today}]"><template v-if="cell.day"><b>{{cell.day}}</b><span v-if="cell.income" class="income">+{{compact(cell.income)}}</span><span v-if="cell.expense" class="expense">−{{compact(cell.expense)}}</span></template></div></div></Card><Card class="transactions"><template #header><Head kicker="TRANSACTIONS" title="最近交易"><div class="seg"><button :class="{active:filter==='all'}" @click="filter='all'">全部</button><button :class="{active:filter==='EXPENSE'}" @click="filter='EXPENSE'">支出</button><button :class="{active:filter==='INCOME'}" @click="filter='INCOME'">收入</button></div></Head></template><div v-if="filteredTransactions.length" class="transaction-table"><Table><thead><tr><th>日期</th><th>描述</th><th>分类</th><th>账户</th><th class="amount">金额</th><th/></tr></thead><tbody><tr v-for="item in filteredTransactions" :key="item.id"><td>{{formatDate(item.occurredOn)}}</td><td><b>{{item.payee||item.note||'未命名交易'}}</b><small v-if="item.note&&item.payee">{{item.note}}</small></td><td>{{item.categoryName||'未分类'}}</td><td>{{item.accountName}}</td><td class="amount" :class="item.kind==='INCOME'?'income':'expense'">{{item.kind==='INCOME'?'+':'−'}}¥{{money(item.amount)}}</td><td><button class="row-action" @click="editTransaction(item)">编辑</button><button class="row-action danger" @click="removeTransaction(item)">删</button></td></tr></tbody></Table></div><div v-else class="ledger-empty"><b>还没有交易</b><Button size="sm" @click="openCreate">记一笔</Button></div><div class="list-footer"><span>显示 {{filteredTransactions.length}} / {{transactions.length}} 笔</span><button class="text-button" @click="loadData">刷新</button></div></Card></div><aside class="ledger-side"><Card><template #header><Head kicker="ACCOUNTS" title="账户"><button class="text-button" @click="openManager">管理</button></Head></template><button v-for="account in accounts" :key="account.id" class="account" @click="openManager"><i>{{accountIcon(account.accountType)}}</i><span><b>{{account.name}}</b><small>{{accountType(account.accountType)}}</small></span><strong>¥{{money(account.balance)}}</strong></button><p v-if="!accounts.length" class="side-empty">添加一个账户开始记账。</p><Button class="account-add" size="sm" variant="ghost" @click="openManager">＋ 添加账户</Button></Card><Card><template #header><Head kicker="RECURRING" title="周期账单"><button class="text-button" @click="openRecurring">新增</button></Head></template><div v-for="bill in recurringBills.slice(0,4)" :key="bill.id" class="recurring"><span><b>{{bill.title}}</b><small>{{frequency(bill.frequency)}} · {{bill.nextDue}}</small></span><strong :class="bill.kind==='INCOME'?'income':'expense'">{{bill.kind==='INCOME'?'+':'−'}}¥{{money(bill.amount)}}</strong></div><p v-if="!recurringBills.length" class="side-empty">还没有周期账单。</p><button class="text-button" @click="runRecurring">立即检查到期账单</button></Card></aside></div>
    <Sheet v-model:open="editorOpen" :title="editing?'编辑交易':'记一笔'"><form class="form" @submit.prevent="saveTransaction"><div class="form-kind"><button :class="{active:form.kind==='EXPENSE'}" type="button" @click="form.kind='EXPENSE'">支出</button><button :class="{active:form.kind==='INCOME'}" type="button" @click="form.kind='INCOME'">收入</button></div><label>金额<input v-model="form.amount" class="ui-input" type="number" step=".01" min=".01" required/></label><label>日期<input v-model="form.occurredOn" class="ui-input" type="date" required/></label><label>账户<select v-model="form.accountId" required><option value="" disabled>选择账户</option><option v-for="a in accounts" :key="a.id" :value="String(a.id)">{{a.name}}</option></select></label><label>分类<select v-model="form.categoryId"><option value="">未分类</option><option v-for="c in categoriesForKind" :key="c.id" :value="String(c.id)">{{categoryPath(c)}}</option></select></label><label>商家 / 描述<input v-model="form.payee" class="ui-input"/></label><label>备注<textarea v-model="form.note" class="ui-textarea"/></label><div class="form-footer"><Button type="button" variant="ghost" @click="editorOpen=false">取消</Button><Button type="submit">保存交易</Button></div></form></Sheet>
    <Drawer v-model:open="managerOpen" title="账户与分类"><div class="manager-tabs"><button :class="{active:managerTab==='accounts'}" @click="managerTab='accounts'">账户</button><button :class="{active:managerTab==='categories'}" @click="managerTab='categories'">分类</button></div><div v-if="managerTab==='accounts'" class="form"><div v-for="a in accounts" :key="a.id" class="manager-row"><span><b>{{a.name}}</b><small>{{accountType(a.accountType)}} · ¥{{money(a.balance)}}</small></span><button class="row-action" @click="removeAccount(a)">删除</button></div><form class="form" @submit.prevent="saveAccount"><input v-model="accountForm.name" class="ui-input" placeholder="账户名称" required/><select v-model="accountForm.accountType"><option value="cash">现金</option><option value="bank">银行卡</option><option value="card">信用卡</option><option value="wallet">电子钱包</option></select><input v-model="accountForm.openingBalance" class="ui-input" type="number" placeholder="期初余额"/><Button size="sm" type="submit">添加账户</Button></form></div><div v-else class="form"><div v-for="c in categories" :key="c.id" class="manager-row"><span><b>{{categoryPath(c)}}</b><small>{{c.kind==='INCOME'?'收入':'支出'}}</small></span><button class="row-action" @click="removeCategory(c)">删除</button></div><form class="form" @submit.prevent="saveCategory"><input v-model="categoryForm.name" class="ui-input" placeholder="分类名称" required/><select v-model="categoryForm.kind"><option value="EXPENSE">支出</option><option value="INCOME">收入</option></select><select v-model="categoryForm.parentId"><option value="">一级分类</option><option v-for="c in parents" :key="c.id" :value="String(c.id)">{{c.name}}</option></select><Button size="sm" type="submit">添加分类</Button></form></div></Drawer>
    <Sheet v-model:open="budgetOpen" title="预算设置"><p class="ai-intro">预算按月和支出分类统计，重复保存会更新对应分类。</p><div v-for="b in budgets" :key="b.id" class="manager-row"><span><b>{{b.category}}</b><small>¥{{money(b.spent)}} / ¥{{money(b.budget)}}</small></span><button class="row-action" @click="deleteBudget(b)">删除</button></div><form class="form" @submit.prevent="saveBudget"><label>月份<input v-model="budgetForm.monthKey" class="ui-input" type="month" required/></label><label>分类<select v-model="budgetForm.categoryId" required><option value="" disabled>选择支出分类</option><option v-for="c in expenses" :key="c.id" :value="String(c.id)">{{categoryPath(c)}}</option></select></label><label>金额<input v-model="budgetForm.amount" class="ui-input" type="number" min=".01" step=".01" required/></label><div class="form-footer"><Button type="button" variant="ghost" @click="budgetOpen=false">关闭</Button><Button type="submit">保存预算</Button></div></form></Sheet>
    <Sheet v-model:open="aiOpen" title="自然语言记账"><p class="ai-intro">说说刚刚发生的交易，助手会整理成可确认的记录。</p><textarea v-model="aiText" class="ui-textarea" placeholder="例如：今天午饭花了 32 元"/><Button class="ai-button" :disabled="aiLoading" @click="aiPreviewRequest">{{aiLoading?'识别中…':'识别交易'}}</Button><div v-if="aiPreview" class="ai-preview"><b :class="aiPreview.kind==='INCOME'?'income':'expense'">{{aiPreview.kind==='INCOME'?'+':'−'}}¥{{money(aiPreview.amount)}}</b><p>{{aiPreview.category}} · {{aiPreview.occurredOn}}</p><p>{{aiPreview.note}}</p><Button @click="confirmAi">确认记账</Button></div></Sheet>
    <Sheet v-model:open="recurringOpen" title="新增周期账单"><form class="form" @submit.prevent="saveRecurring"><label>名称<input v-model="recurringForm.title" class="ui-input" required/></label><label>金额<input v-model="recurringForm.amount" class="ui-input" type="number" min=".01" step=".01" required/></label><label>账户<select v-model="recurringForm.accountId" required><option value="" disabled>选择账户</option><option v-for="a in accounts" :key="a.id" :value="String(a.id)">{{a.name}}</option></select></label><label>分类<select v-model="recurringForm.categoryId"><option value="">未分类</option><option v-for="c in expenses" :key="c.id" :value="String(c.id)">{{categoryPath(c)}}</option></select></label><label>频率<select v-model="recurringForm.frequency"><option value="MONTHLY">每月</option><option value="WEEKLY">每周</option><option value="YEARLY">每年</option></select></label><label>下次到期<input v-model="recurringForm.nextDue" class="ui-input" type="date" required/></label><div class="form-footer"><Button type="button" variant="ghost" @click="recurringOpen=false">取消</Button><Button type="submit">保存周期账单</Button></div></form></Sheet>
  </section>
</template>

<script setup>
import { computed, h, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import * as echarts from 'echarts'
import { ElMessage } from 'element-plus'
import Card from '../components/ui/Card.vue'; import Button from '../components/ui/Button.vue'; import Table from '../components/ui/Table.vue'; import Sheet from '../components/ui/Sheet.vue'; import Drawer from '../components/ui/Drawer.vue'
import { createLedgerSyncEngine } from '../../packages/sync-engine/src/index.js'
import { apiCreateLedgerAccount, apiCreateLedgerBudget, apiCreateLedgerCategory, apiCreateLedgerTransaction, apiDeleteLedgerAccount, apiDeleteLedgerBudget, apiDeleteLedgerCategory, apiDeleteLedgerTransaction, apiGetLedgerReports, apiImportLedgerCsv, apiImportLedgerExcel, apiLedgerAiConfirm, apiLedgerAiPreview, apiListLedgerAccounts, apiListLedgerCategories, apiListLedgerTransactions, apiListRecurringBills, apiPullLedgerSync, apiPushLedgerSync, apiUpdateLedgerTransaction } from '../api'

const Head={props:['kicker','title','right'],setup(props,{slots}){return()=>h('div',{class:'head'},[h('div',[h('div',{class:'kicker'},props.kicker),h('h2',props.title)]),h('div',{class:'head-right'},[slots.default?.(),props.right?h('span',props.right):null])])}}
const dateNow=()=>{const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}; const today=dateNow(); const selectedMonth=ref(today.slice(0,7))
const accounts=ref([]),categories=ref([]),transactions=ref([]),reports=ref({}),annualReport=ref({}),budgets=ref([]),recurringBills=ref([]),online=ref(navigator.onLine),syncing=ref(false),filter=ref('all'),categoryScope=ref('month'),categoryLevel=ref('primary')
const editorOpen=ref(false),editing=ref(null),managerOpen=ref(false),managerTab=ref('accounts'),budgetOpen=ref(false),aiOpen=ref(false),aiText=ref(''),aiPreview=ref(null),aiLoading=ref(false),recurringOpen=ref(false)
const form=reactive({kind:'EXPENSE',amount:'',occurredOn:today,accountId:'',categoryId:'',payee:'',note:''}); const accountForm=reactive({name:'',accountType:'cash',openingBalance:''}); const categoryForm=reactive({name:'',kind:'EXPENSE',parentId:''}); const budgetForm=reactive({monthKey:selectedMonth.value,categoryId:'',amount:''}); const recurringForm=reactive({title:'',amount:'',accountId:'',categoryId:'',frequency:'MONTHLY',nextDue:today})
const dailyRef=ref(null),categoryRef=ref(null),barRef=ref(null),lineRef=ref(null),budgetRef=ref(null),chartMap=new Map(); let themeObserver; const weekdays=['日','一','二','三','四','五','六']; const selectedYear=computed(()=>selectedMonth.value.slice(0,4)); const monthLabel=computed(()=>`${selectedYear.value} 年 ${Number(selectedMonth.value.slice(5))} 月`); const monthStart=computed(()=>`${selectedMonth.value}-01`); const monthEnd=computed(()=>endOfMonth(selectedMonth.value)); const yearStart=computed(()=>`${selectedYear.value}-01-01`); const yearEnd=computed(()=>`${selectedYear.value}-12-31`)
const range=(d,a,b)=>String(d||'')>=a&&String(d||'')<=b; const sum=rows=>{const income=rows.filter(x=>x.kind==='INCOME').reduce((n,x)=>n+Number(x.amount||0),0),expense=rows.filter(x=>x.kind==='EXPENSE').reduce((n,x)=>n+Number(x.amount||0),0);return{income,expense,net:income-expense,incomeCount:rows.filter(x=>x.kind==='INCOME').length,expenseCount:rows.filter(x=>x.kind==='EXPENSE').length}}; const monthItems=computed(()=>transactions.value.filter(x=>range(x.occurredOn,monthStart.value,monthEnd.value))); const summary=computed(()=>sum(monthItems.value)); const totalBalance=computed(()=>accounts.value.reduce((n,x)=>n+Number(x.balance||0),0)); const categoriesForKind=computed(()=>categories.value.filter(x=>x.kind===form.kind)); const expenses=computed(()=>categories.value.filter(x=>x.kind==='EXPENSE')); const parents=computed(()=>categories.value.filter(x=>x.kind===categoryForm.kind&&!x.parentId)); const filteredTransactions=computed(()=>transactions.value.filter(x=>filter.value==='all'||x.kind===filter.value).slice(0,12));
const dailyRows=computed(()=>Array.from({length:Number(monthEnd.value.slice(-2))},(_,i)=>{const date=`${selectedMonth.value}-${String(i+1).padStart(2,'0')}`;return{date,...sum(monthItems.value.filter(x=>x.occurredOn===date))}})); const budgetSummary=computed(()=>reports.value.budgetSummary||reports.value.budget_summary||{budget:budgets.value.reduce((n,x)=>n+Number(x.budget||0),0),spent:budgets.value.reduce((n,x)=>n+Number(x.spent||0),0)}); const budgetLeft=computed(()=>Number(budgetSummary.value.budget||0)-Number(budgetSummary.value.spent||0)); const rank=computed(()=>{const map=new Map; for(const x of ((categoryScope.value==='month'?reports.value:annualReport.value).categories||[]).filter(x=>x.kind==='EXPENSE')){const key=categoryLevel.value==='primary'?(x.parent_category||x.parentCategory||x.category||'未分类'):(x.category||'未分类');map.set(key,(map.get(key)||0)+Number(x.amount||0))}return[...map].map(([name,amount])=>({name,amount})).sort((a,b)=>b.amount-a.amount).slice(0,8)}); const months=computed(()=>{const map=new Map((annualReport.value.monthly||[]).map(x=>[x.month,x]));return Array.from({length:12},(_,i)=>{const x=map.get(`${selectedYear.value}-${String(i+1).padStart(2,'0')}`)||{},income=Number(x.income||0),expense=Number(x.expense||0);return{label:`${i+1}月`,income,expense,net:income-expense}})}); const weekStart=()=>{const d=new Date(`${today}T00:00:00`);d.setDate(d.getDate()-(d.getDay()||7)+1);return d.toISOString().slice(0,10)}; const snapshots=computed(()=>[{label:'今天',range:today.replaceAll('-','.'),...sum(transactions.value.filter(x=>x.occurredOn===today))},{label:'本周',range:`${weekStart().slice(5).replace('-','.')} - ${today.slice(5).replace('-','.')}`,...sum(transactions.value.filter(x=>range(x.occurredOn,weekStart(),today)))},{label:'本年',range:`${selectedYear.value}.01.01 - ${selectedYear.value}.12.31`,...sum(transactions.value.filter(x=>range(x.occurredOn,yearStart.value,yearEnd.value)))}]); const calendarCells=computed(()=>{const blank=new Date(`${selectedMonth.value}-01T00:00:00`).getDay(),days=dailyRows.value.map(x=>({key:x.date,day:+x.date.slice(-2),income:x.income,expense:x.expense,today:x.date===today}));return[...Array.from({length:blank},(_,i)=>({key:`a${i}`})),...days,...Array.from({length:(7-(blank+days.length)%7)%7},(_,i)=>({key:`b${i}`}))]})
const money=x=>Number(x||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2}); const compact=x=>Number(x)>=1000?`${(Number(x)/1000).toFixed(1)}k`:Number(x).toFixed(0); const formatDate=x=>String(x||'').replaceAll('-','/'); const endOfMonth=m=>{const [y,n]=m.split('-').map(Number);return`${m}-${String(new Date(y,n,0).getDate()).padStart(2,'0')}`}; const accountIcon=x=>({cash:'¥',bank:'▣',card:'▤',wallet:'◒'})[x]||'·'; const accountType=x=>({cash:'现金',bank:'银行卡',card:'信用卡',wallet:'电子钱包'})[x]||'其他账户'; const frequency=x=>({MONTHLY:'每月',WEEKLY:'每周',YEARLY:'每年'})[x]||'每月'; const categoryPath=x=>{const p=categories.value.find(y=>String(y.id)===String(x.parentId));return p?`${p.name} / ${x.name}`:x.name}; const shiftMonth=n=>{const [y,m]=selectedMonth.value.split('-').map(Number);selectedMonth.value=new Date(y,m-1+n,1).toISOString().slice(0,7)}
const engine=createLedgerSyncEngine({push:apiPushLedgerSync,pull:apiPullLedgerSync}); async function loadData(){try{const[a,c,t,r,annual,recurring]=await Promise.all([apiListLedgerAccounts(),apiListLedgerCategories(),apiListLedgerTransactions({from:yearStart.value,to:yearEnd.value,limit:500}),apiGetLedgerReports({from:monthStart.value,to:monthEnd.value}),apiGetLedgerReports({from:yearStart.value,to:yearEnd.value}),apiListRecurringBills()]);accounts.value=a||[];categories.value=c||[];transactions.value=t||[];reports.value=r||{};annualReport.value=annual||{};budgets.value=r?.budgets||[];recurringBills.value=recurring||[];budgetForm.monthKey=selectedMonth.value;online.value=true;await cache();await draw()}catch(e){online.value=false;accounts.value=await engine.list('account');categories.value=await engine.list('category');transactions.value=await engine.list('transaction');await draw()}} async function cache(){await Promise.all([...accounts.value.map(x=>engine.put('account',x,{opId:`server-a-${x.id}-${x.revision}`,recordOp:false})),...categories.value.map(x=>engine.put('category',x,{opId:`server-c-${x.id}-${x.revision}`,recordOp:false})),...transactions.value.map(x=>engine.put('transaction',x,{opId:`server-t-${x.id}-${x.revision}`,recordOp:false}))])}
function init(key,el){if(!el||!el.clientWidth||!el.clientHeight)return;chartMap.get(key)?.dispose();const c=echarts.init(el);chartMap.set(key,c);return c} async function draw(){await nextTick();await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const s=getComputedStyle(document.documentElement),text=s.getPropertyValue('--ink2').trim()||'#49505c',line=s.getPropertyValue('--line').trim()||'#e2ded4',accent=s.getPropertyValue('--accent').trim()||'#0f5132',tip={trigger:'axis',valueFormatter:v=>`¥${money(v)}`};const axis={axisLine:{lineStyle:{color:line}},axisLabel:{color:text,fontSize:10}};init('daily',dailyRef.value)?.setOption({grid:{left:12,right:16,top:16,bottom:24,containLabel:true},tooltip:tip,xAxis:{type:'category',data:dailyRows.value.map(x=>x.date.slice(-2)),...axis},yAxis:{type:'value',axisLabel:{color:text,fontSize:10},splitLine:{lineStyle:{color:line,type:'dashed'}}},series:[{name:'支出',type:'line',smooth:true,symbol:'circle',symbolSize:5,data:dailyRows.value.map(x=>x.expense),lineStyle:{color:'#b54708',width:2},areaStyle:{color:'rgba(181,71,8,.12)'}}]}); const r=[...rank.value].reverse();init('category',categoryRef.value)?.setOption({grid:{left:12,right:28,top:14,bottom:12,containLabel:true},tooltip:tip,xAxis:{type:'value',axisLabel:{color:text,fontSize:10},splitLine:{lineStyle:{color:line,type:'dashed'}}},yAxis:{type:'category',data:r.map(x=>x.name),axisTick:{show:false},axisLine:{show:false},axisLabel:{color:text,fontSize:11}},series:[{type:'bar',data:r.map(x=>x.amount),barMaxWidth:18,itemStyle:{color:accent,borderRadius:[0,3,3,0]}}]});const opts={grid:{left:12,right:12,top:30,bottom:24,containLabel:true},tooltip:tip,legend:{data:['收入','支出','结余'],textStyle:{color:text,fontSize:10},right:0,top:0},xAxis:{type:'category',data:months.value.map(x=>x.label),...axis},yAxis:{type:'value',axisLabel:{color:text,fontSize:10},splitLine:{lineStyle:{color:line,type:'dashed'}}}};init('bar',barRef.value)?.setOption({...opts,series:[{name:'收入',type:'bar',data:months.value.map(x=>x.income),barMaxWidth:12,itemStyle:{color:accent}},{name:'支出',type:'bar',data:months.value.map(x=>x.expense),barMaxWidth:12,itemStyle:{color:'#b54708'}},{name:'结余',type:'bar',data:months.value.map(x=>x.net),barMaxWidth:12,itemStyle:{color:'#5b7c99'}}]});init('line',lineRef.value)?.setOption({...opts,series:[{name:'收入',type:'line',smooth:true,symbol:'none',data:months.value.map(x=>x.income),lineStyle:{color:accent,width:2}},{name:'支出',type:'line',smooth:true,symbol:'none',data:months.value.map(x=>x.expense),lineStyle:{color:'#b54708',width:2}},{name:'结余',type:'line',smooth:true,symbol:'none',data:months.value.map(x=>x.net),lineStyle:{color:'#5b7c99',width:2}}]});const spent=+budgetSummary.value.spent||0,budget=+budgetSummary.value.budget||0;init('budget',budgetRef.value)?.setOption({series:[{type:'pie',radius:['70%','91%'],label:{show:false},data:budget?[{name:'已支出',value:Math.min(spent,budget),itemStyle:{color:spent>budget?'#b42318':accent}},{name:'剩余预算',value:Math.max(budget-spent,0),itemStyle:{color:line}}]:[{name:'未设置预算',value:1,itemStyle:{color:line}}]}]})}
function openCreate(){editing.value=null;Object.assign(form,{kind:'EXPENSE',amount:'',occurredOn:today,accountId:accounts.value[0]?String(accounts.value[0].id):'',categoryId:'',payee:'',note:''});editorOpen.value=true} function editTransaction(x){editing.value=x;Object.assign(form,{kind:x.kind,amount:x.amount,occurredOn:x.occurredOn,accountId:String(x.accountId),categoryId:x.categoryId?String(x.categoryId):'',payee:x.payee||'',note:x.note||''});editorOpen.value=true} async function saveTransaction(){const p={...form,amount:+form.amount,accountId:+form.accountId,categoryId:form.categoryId?+form.categoryId:null,clientOpId:`web-${Date.now()}`};try{if(editing.value)await apiUpdateLedgerTransaction(editing.value.id,p,editing.value.revision);else await apiCreateLedgerTransaction(p,p.clientOpId);editorOpen.value=false;ElMessage.success('交易已保存');await loadData()}catch(e){ElMessage.error(e.response?.data?.detail||'保存失败')}} async function removeTransaction(x){if(!confirm('删除后交易仍保留历史记录，确定删除？'))return;try{await apiDeleteLedgerTransaction(x.id,x.revision);await loadData()}catch(e){ElMessage.error('删除失败')}} function openManager(){managerOpen.value=true} async function saveAccount(){try{await apiCreateLedgerAccount({...accountForm,openingBalance:+(accountForm.openingBalance||0)});Object.assign(accountForm,{name:'',accountType:'cash',openingBalance:''});await loadData()}catch(e){ElMessage.error('账户保存失败')}} async function removeAccount(x){try{await apiDeleteLedgerAccount(x.id,x.revision);await loadData()}catch(e){ElMessage.error('账户删除失败')}} async function saveCategory(){try{await apiCreateLedgerCategory({...categoryForm,parentId:categoryForm.parentId?+categoryForm.parentId:null});Object.assign(categoryForm,{name:'',kind:'EXPENSE',parentId:''});await loadData()}catch(e){ElMessage.error('分类保存失败')}} async function removeCategory(x){try{await apiDeleteLedgerCategory(x.id,x.revision);await loadData()}catch(e){ElMessage.error('分类删除失败')}} function openBudget(){Object.assign(budgetForm,{monthKey:selectedMonth.value,categoryId:'',amount:''});budgetOpen.value=true} async function saveBudget(){try{await apiCreateLedgerBudget({monthKey:budgetForm.monthKey,categoryId:+budgetForm.categoryId,amount:+budgetForm.amount});await loadData();ElMessage.success('预算已保存')}catch(e){ElMessage.error('预算保存失败')}} async function deleteBudget(x){try{await apiDeleteLedgerBudget(x.id);await loadData()}catch(e){ElMessage.error('预算删除失败')}} async function importFile(e){const f=e.target.files?.[0];if(!f)return;try{const rows=/\.xlsx?$/i.test(f.name)?await apiImportLedgerExcel(f):await apiImportLedgerCsv(f);ElMessage.success(`已导入 ${rows?.length||0} 笔交易`);await loadData()}catch(x){ElMessage.error(x.response?.data?.detail||'导入失败')}finally{e.target.value=''}} function exportCsv(){const header='交易类型,日期,一级分类,二级分类,收入账户,金额,成员,商家,项目,备注';const rows=transactions.value.map(x=>{const c=categories.value.find(y=>String(y.id)===String(x.categoryId)),p=c&&categories.value.find(y=>String(y.id)===String(c.parentId));return[x.kind==='INCOME'?'收入':'支出',x.occurredOn,p?.name||x.categoryName||'',p?x.categoryName||'':'',x.accountName||'',x.amount,'',x.payee||'','',x.note||''].map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')});const u=URL.createObjectURL(new Blob([`\ufeff${[header,...rows].join('\n')}`],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=`ledger-${selectedMonth.value}.csv`;a.click();URL.revokeObjectURL(u)}
function openRecurring(){Object.assign(recurringForm,{title:'',amount:'',accountId:accounts.value[0]?String(accounts.value[0].id):'',categoryId:'',frequency:'MONTHLY',nextDue:today});recurringOpen.value=true} async function saveRecurring(){try{const{apiCreateRecurringBill}=await import('../api');await apiCreateRecurringBill({...recurringForm,amount:+recurringForm.amount,accountId:+recurringForm.accountId,categoryId:recurringForm.categoryId?+recurringForm.categoryId:null});recurringOpen.value=false;await loadData()}catch(e){ElMessage.error('周期账单保存失败')}} async function runRecurring(){try{const{apiRunRecurringBills}=await import('../api');const r=await apiRunRecurringBills();ElMessage.success(`已生成 ${r.generated||0} 笔交易`);await loadData()}catch(e){ElMessage.error('周期账单检查失败')}} async function aiPreviewRequest(){if(!aiText.value.trim())return;aiLoading.value=true;try{aiPreview.value=await apiLedgerAiPreview(aiText.value)}catch(e){ElMessage.error('暂时无法识别')}finally{aiLoading.value=false}} async function confirmAi(){try{await apiLedgerAiConfirm(aiPreview.value);aiOpen.value=false;await loadData();ElMessage.success('AI 记账完成')}catch(e){ElMessage.error('记账失败')}}
watch(selectedMonth,loadData);watch([categoryScope,categoryLevel],draw);onMounted(()=>{window.addEventListener('resize',()=>chartMap.forEach(x=>x.resize()));window.addEventListener('online',loadData);themeObserver=new MutationObserver(draw);themeObserver.observe(document.documentElement,{attributes:true,attributeFilter:['class']});loadData()});onBeforeUnmount(()=>{themeObserver?.disconnect();chartMap.forEach(x=>x.dispose())})
